        const fontUploader = window.wp.media({
            title: __('Select or Upload Font File', 'nexter-extension'),
            button: {
                text: __('Use this file', 'nexter-extension'),
            },
            library: {
                type: ['font/woff2', 'font/ttf', 'font/otf', 'font/woff', 'application/x-font-ttf'], // Restrict to .woff2 and .ttf
            },
            multiple: false,
        });

        fontUploader.on('select', () => {
            const attachment = fontUploader.state().get('selection').first().toJSON();
            if( fontType == 'simple'){
                if(type == 'edit'){
                    const updateSimpleList = { ...simpleList }
                    updateSimpleList[key].filename = attachment.filename
                    updateSimpleList[key].id = attachment.id
                    setSimpleList(updateSimpleList)
                }else{
                    const updateSimpleList = { ...simpleDefList }
                    updateSimpleList[key].filename = attachment.filename
                    updateSimpleList[key].id = attachment.id
                    setSimpleDefList(updateSimpleList)
                }
            }else{
                if(type == 'edit'){
                    setVariableList(editFontVId, key, attachment)
                }else{
                    const updatedSettings = { ...defaultVariable };
                    defaultVariable[VariableUniId].variablefont.lists[key].filename = attachment.filename;
                    defaultVariable[VariableUniId].variablefont.lists[key].id = attachment.id;
                    setDefaultVariable(updatedSettings);
                }
            }
        });

        wp.media.frame.on('upload:complete', function() {
            fontUploader.state().get('library').observeChanges();
        });
