    useEffect(() => {

        const handleEscapeKey = (event) => {
            if (event.key === 'Escape') {
                setIsPopupVisible(false);
                setPopupData(null);
                setPopupInputValue({});
            }
        };

        document.addEventListener('keydown', handleEscapeKey);

        return () => {
            document.removeEventListener('keydown', handleEscapeKey);
        };
    }, []);
    const handleKeyDown = (event) => {
        if((event.metaKey && event.key === 'a') || (event.ctrlKey && event.key === 'a')) {
            event.preventDefault();
            Object.entries(wpTables).map(([id, name]) => {
                const updatedSettings = { ...replaceOpt };
                const index = updatedSettings['wp-replace-url']['tables'].indexOf(id);
                if (index === -1) {
                    updatedSettings['wp-replace-url']['tables'].push(id);
                }
                setReplaceOpt(updatedSettings);
            })
        }
    };

    const fetchWpTables = async () => {
        if (Object.keys(wpTables).length > 0) {
            return;
        }
        
        setIsLoadingTables(true);
        
        try {
            const formData = new FormData();
            formData.append('action', 'nexter_get_replace_url_tables');
            formData.append('nexter_nonce', nexter_admin_config.ajax_nonce);
            
            const response = await fetch(nxtext_ajax_object?.ajax_url, {
                method: 'POST',
                body: formData,
            });
            
            const result = await response.json();
            
            if (result.success && result.data.tables) {
                setWpTables(result.data.tables);
            }
        } catch (error) {
            //console.error('Error fetching tables:', error);
        } finally {
            setIsLoadingTables(false);
        }
    };

    const handleOpenPopup = (data) => {
        setReplaceorElse(data.key)
        setPopupData(data);
        const initialPopupInputValue = {};
        Object.keys(data.formField).forEach(key => {
            initialPopupInputValue[key] = enabledSettings[key] || '';
        });
        setPopupInputValue(initialPopupInputValue);
        setIsPopupVisible(true);
        // Fetch tables data when Replace URL popup opens
        if (data.key === 'wp-replace-url') {
            fetchWpTables();
        }
    };

    const handleClosePopup = () => {
        setSimpleFont(false);
        setVariableFont(false)
        setSimpleFontEdit(false);
        setIsContentDisabled(true);
        setIsPopupVisible(false);
        setPopupData(null);
        setPopupInputValue({});
    };

    const replaceButtonClick = async (e) => {
        
        let popWrap = e.target.closest('.nxtext_settings_popup');
        let cardWrap = popWrap.querySelector('.nxtext_field_card_cover');
    
        let getID = cardWrap.getAttribute('id'); 
        if (popupData) {
            setEnabledSettings((prevState) => ({
                ...prevState,
                ...popupInputValue,
            }));

            let replaceData = replaceOpt[getID]
            setReplaceMsg('');
            setProcessReplace(true);
            if (!replaceData.from || !replaceData.from) {
                setReplaceMsg('Please Enter Old URL/Text.');
                setProcessReplace(false);
                return;
            }
            if (!replaceData.to || !replaceData.to) {
                setReplaceMsg('Please Enter New URL/Text.');
                setProcessReplace(false);
                return;
            }
            if (!replaceData.tables || !replaceData.tables.length) {
                setReplaceMsg('Select any table before replace');
                setProcessReplace(false);
                return;
            }

            const formData = new FormData();
            formData.append('extension_type', getID);
            formData.append('action', 'nxt_replace_url');
            Object.entries(replaceOpt[getID]).forEach(([key, value]) => {
                if(key == 'tables'){
                    formData.append(key, JSON.stringify(value));
                }else{
                    formData.append(key, value);
                }
            });
            
            formData.append('nexter_nonce', nxtext_ajax_object.ajax_nonce);
                    
            // handleClosePopup();
            await nxtReplaceBtnClick(e, formData, setReplaceFind, 'replace')
            setProcessReplace(false);
        }
    };

    const handlePopupSave = (e) => {
        if(simpleFont && validateDefaultSimple(defaultSimple, false)){
            const updatedSettings = { ...enabledSettings };    
            updatedSettings['custom-upload-font'].values.push(defaultSimple);    
            setEnabledSettings(updatedSettings);
        }else if(variableFont && validateDefaultVariable(defaultVariable, false)){
            const updatedSettings = { ...enabledSettings };    
            updatedSettings['custom-upload-font'].values.push(defaultVariable);    
            setEnabledSettings(updatedSettings);
        }

        let popWrap = e.target.closest('.nxtext_settings_popup');
        let cardWrap = popWrap.querySelector('.nxtext_field_card_cover');
    
        let getID = cardWrap.getAttribute('id'); 
        if (popupData) {
            setEnabledSettings((prevState) => ({
                ...prevState,
                ...popupInputValue,
            }));

            const formData = new FormData();

            if(getID != 'wp-replace-url' && getID != 'adobe-font' && getID != 'regenerate-thumbnails'){
                formData.append('action', 'nexter_ext_save_data');
            }
            formData.append('extension_type', getID);
            if(getID == 'wp-duplicate-post'){
                formData.append('wpDupPostSet', JSON.stringify(enabledSettings[getID].values)); 
            }else if(getID == 'content-post-order'){
                formData.append('post_types', JSON.stringify(enabledSettings[getID].values)); 
            }else if(getID == 'disable-gutenberg'){
                formData.append('disable_gutenberg_posts', JSON.stringify(enabledSettings[getID].values)); 
            }else if(getID == 'public-preview-drafts'){
                formData.append('preview_drafts', JSON.stringify(enabledSettings[getID].values)); 
            }else if(getID == 'taxonomy-order'){
                formData.append('taxonomy_order', JSON.stringify(enabledSettings[getID].values)); 
            }else if(getID == 'redirect-404-page'){
                formData.append('redirect_404', enabledSettings[getID].values); 
            }else if(getID == 'wp-replace-url'){
                formData.append('action', 'nxt_replace_confirm_url');
                Object.entries(replaceOpt[getID]).forEach(([key, value]) => {
                    if(key == 'tables'){
                        formData.append(key, JSON.stringify(value));
                    }else{
                        formData.append(key, value);
                    }
                });
            }else if(getID == 'custom-upload-font'){
                formData.append('fonts', JSON.stringify(enabledSettings[getID].values));
            }else if(getID == 'adobe-font'){
                formData.append('action', 'nexter_ext_save_adobe_font_data');
                formData.append('project_id', enabledSettings[getID].values.project_id);
            }else if(getID == 'regenerate-thumbnails'){
                formData.append('action', 'nexter_regenerate_image_thumbnails');

                let joinedValues = Object.keys(regen_thumbneils).filter(item => !disable_image_size.includes(regen_thumbneils[item])).map(item => regen_thumbneils[item]).join(',');
                                
                formData.append('image_sizes_to_be_generated', joinedValues);
            }else if(getID == 'smtp-email'){
                formData.append('smtpEmail', JSON.stringify(enabledSettings[getID].values));
            }
            
            formData.append('nexter_nonce', nxtext_ajax_object.ajax_nonce);
                    
            // handleClosePopup();
            if(getID != 'wp-replace-url' && getID != 'adobe-font' && getID != 'regenerate-thumbnails' && getID != 'custom-upload-font'){
                nxtdash_save_data(e, formData)
            }else if(getID == 'wp-replace-url'){
                nxtReplaceBtnClick(e, formData, setReplaceFind, 'confirm');
                setReplaceOpt(defaultReplaceOpt)
                setReplaceFind(false)
            }else if(getID == 'adobe-font'){
                nxtAdobeFontGet(e, formData, enabledSettings, setEnabledSettings);            
            }else if(getID == 'regenerate-thumbnails'){
                let joinedValues = Object.keys(regen_thumbneils).filter(item => !disable_image_size.includes(regen_thumbneils[item])).map(item => regen_thumbneils[item]).join(',');
                nxtRegenerateThumb(e, formData,nxtext_ajax_object.ajax_nonce, joinedValues)
            }else if(getID == 'custom-upload-font'){
                if(simpleFont && validateDefaultSimple(defaultSimple, true)){
                    nxtdash_save_simplefont(e, formData, setDefaultSimple, setSimpleUniId, setSimpleFont, setIsContentDisabled);                   
                }else if(variableFont && validateDefaultVariable(defaultVariable, true)){
                    nxtdash_save_variablefont(e, formData, setDefaultVariable, setVariableUniId, setVariableFont, setIsContentDisabled);
                }else if(!simpleFont && !variableFont){
                    nxtdash_save_data(e, formData, handleBack)
                }
            }
        }
    };

