    const getFontData = (editFontSId) => {
        for (let i = 0; i < enabledSettings['custom-upload-font'].values.length; i++) {
          if (enabledSettings['custom-upload-font'].values[i].hasOwnProperty(editFontSId)) {
            return enabledSettings['custom-upload-font'].values[i][editFontSId];
          }
        }
        return null;
    };
    const setFontName = (editFontSId, value) => {
        for (let i = 0; i < enabledSettings['custom-upload-font'].values.length; i++) {
          if (enabledSettings['custom-upload-font'].values[i].hasOwnProperty(editFontSId)) {            
            const updatedSettings = { ...enabledSettings };
            enabledSettings['custom-upload-font'].values[i][editFontSId].simplefont.font_name = value
            setEnabledSettings(updatedSettings);
          }
        }
    };
    const setVFontName = (editFontVId, value) => {
        for (let i = 0; i < enabledSettings['custom-upload-font'].values.length; i++) {
          if (enabledSettings['custom-upload-font'].values[i].hasOwnProperty(editFontVId)) {            
            const updatedSettings = { ...enabledSettings };
            enabledSettings['custom-upload-font'].values[i][editFontVId].variablefont.font_name = value
            setEnabledSettings(updatedSettings);
          }
        }
    };
    
    const updateSimpleLists = (editFontSId, updatedList, type) => {
        if(type=='edit'){
            for (let i = 0; i < enabledSettings['custom-upload-font'].values.length; i++) {
              if (enabledSettings['custom-upload-font'].values[i].hasOwnProperty(editFontSId)) {            
                const updatedSettings = { ...enabledSettings };
                enabledSettings['custom-upload-font'].values[i][editFontSId].simplefont.lists = updatedList
                setEnabledSettings(updatedSettings);
              }
            }
        }else{      
            const updatedSettings = { ...defaultSimple };
            updatedSettings[editFontSId].simplefont.lists = updatedList
            setDefaultSimple(updatedSettings);
        }
    };
    const handleAddRow = (editFontSId, type) => {        
        const newId = generateUniqueId();
        const newRow = {
            id: '',
            filename: '',
            variation: '100'
        };

        if(type == 'edit'){
            setSimpleList((prevList) => {
                const updatedList = {
                  ...prevList,
                  [newId]: newRow
                };
            
                updateSimpleLists(editFontSId, updatedList, type);
            
                return updatedList;
            });
        }else{
            setSimpleDefList((prevList) => {
                const updatedList = {
                    ...prevList,
                    [newId]: newRow
                };
            
                updateSimpleLists(editFontSId, updatedList, type);
            
                return updatedList;
            });
        }
    };

    const handleRemoveRow = (editFontSId, key, type) => {
        if(type == 'edit'){
            setSimpleList((prevList) => {
              const updatedList = Object.fromEntries(
                Object.entries(prevList).filter(([id]) => id !== key)
              );
          
              // Pass the updated list to removeSimpleList after state update
              updateSimpleLists(editFontSId, updatedList, type);
          
              return updatedList;
            });
        }else{
            setSimpleDefList((prevList) => {
                const updatedList = Object.fromEntries(
                  Object.entries(prevList).filter(([id]) => id !== key)
                );
            
                // Pass the updated list to removeSimpleList after state update
                updateSimpleLists(editFontSId, updatedList, type);
            
                return updatedList;
              });
        }
    };

