        // Add or remove value
        const index = updatedSettings[field].values[key].indexOf(value);
        if (index > -1) {
            updatedSettings[field].values[key].splice(index, 1); // Remove
        } else {
            updatedSettings[field].values[key].push(value); // Add
        }
    
        setEnabledSettings(updatedSettings);
